export function getAreasForState(state?: string | null, extraDbCities: string[] = []): string[] {
  if (!state || state === "all") return [];
  const normalized = state.trim().toLowerCase().replace(/ss/g, 's');

  const stateKey = Object.keys(NIGERIAN_STATE_AREAS).find(
    (k) =>
      k.toLowerCase().replace(/ss/g, 's') === normalized ||
      ((normalized === "fct" || normalized === "abuja") && k.includes("Federal Capital"))
  );

  const standard = stateKey ? NIGERIAN_STATE_AREAS[stateKey] : [];
  const set = new Set<string>();
  extraDbCities.forEach((c) => {
    if (c && c.trim()) set.add(c.trim());
  });
  standard.forEach((c) => set.add(c));
  return Array.from(set);
}

export const getCitiesForState = getAreasForState;
export const NIGERIAN_STATE_CITIES = NIGERIAN_STATE_AREAS;
